begin;
select no_plan();
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000001501','beta14@test.local'),('00000000-0000-4000-8000-000000001502','other14@test.local');
insert into public.families(id,name,created_by) values('10000000-0000-4000-8000-000000001501','Beta','00000000-0000-4000-8000-000000001501'),('10000000-0000-4000-8000-000000001502','Other','00000000-0000-4000-8000-000000001502');
insert into public.family_members(family_id,user_id) values('10000000-0000-4000-8000-000000001501','00000000-0000-4000-8000-000000001501'),('10000000-0000-4000-8000-000000001502','00000000-0000-4000-8000-000000001502');
insert into public.children(id,family_id,name) values('20000000-0000-4000-8000-000000001502','10000000-0000-4000-8000-000000001502','Other child');
insert into public.family_rewards(id,family_id,title,cost_stars) values('30000000-0000-4000-8000-000000001501','10000000-0000-4000-8000-000000001501','Book',20);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000001501","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000001501","role":"parent"}}',true);
select throws_ok($$select public.set_beta_test_plan('pro')$$,'42501','beta_access_required','regular parent cannot grant own package');
select is((select count(*)::int from public.get_beta_test_access()),0,'non tester has no beta controls');
select throws_ok($$insert into public.beta_test_access values(auth.uid(),gina.family_id(),now()+interval '1 day','hack')$$,'42501',null,'cannot self allowlist');
select throws_ok($$select public.set_child_goal('30000000-0000-4000-8000-000000001501','20000000-0000-4000-8000-000000001502')$$,'42501','child_not_found','cannot change a different family child goal');
reset role;
insert into public.beta_test_access values('00000000-0000-4000-8000-000000001501','10000000-0000-4000-8000-000000001501',now()+interval '2 days','beta test');
set local role authenticated;
select lives_ok($$select public.set_beta_test_plan('pro')$$,'allowed tester can try Pro');
select is((select plan::text from public.get_family_entitlement()),'pro','public entitlement uses beta');
select is((public.get_prova_entitlement()->>'plan'),'pro','AI entitlement uses beta');
select lives_ok($$select public.set_beta_test_plan('free')$$,'tester can downgrade to Free');
select is((public.get_prova_entitlement()->>'ai_generate_limit')::int,0,'Free actually disables AI quota');
select lives_ok($$select public.set_beta_test_plan('plus')$$,'tester can try Plus');
select lives_ok($$select public.save_child_setup('40000000-0000-4000-8000-000000001501',jsonb_build_object('name','New child','birth_year',extract(year from now())::int-8,'grade',2,'gender','unspecified','interests',jsonb_build_array('reading')),'[{"title":"Read","icon":"read-book","stars":2,"days":[1,3,5]}]')$$,'child and selected routine saved together');
select is((select count(*)::int from public.children where family_id=gina.family_id()),1,'one child saved');
select is((select count(*)::int from public.task_templates where family_id=gina.family_id()),1,'one chosen task saved');
select lives_ok($$select public.save_child_setup('40000000-0000-4000-8000-000000001501',jsonb_build_object('name','New child','birth_year',extract(year from now())::int-8,'grade',2,'gender','unspecified','interests',jsonb_build_array('reading')),'[{"title":"Read","icon":"read-book","stars":2,"days":[1,3,5]}]')$$,'lost response can be retried');
select is((select count(*)::int from public.task_templates where family_id=gina.family_id()),1,'retry does not duplicate tasks');
select throws_ok($$select public.save_child_setup('40000000-0000-4000-8000-000000001501','{"name":"Changed","birth_year":2020}')$$,'P0001','request_conflict','same request cannot be changed');
select throws_ok($$select public.save_child_setup('40000000-0000-4000-8000-000000001502',jsonb_build_object('name','Invalid tasks','birth_year',extract(year from now())::int-6),'[{"title":"Invalid","stars":99,"days":[1]}]')$$,'23514',null,'invalid task rolls back profile');
select is((select count(*)::int from public.children where family_id=gina.family_id()),1,'failed setup leaves no partial child');
select throws_ok($$select public.save_child_setup('40000000-0000-4000-8000-000000001503',jsonb_build_object('name','Other child','birth_year',extract(year from now())::int-7),'[]','20000000-0000-4000-8000-000000001502')$$,'42501','child_not_found','cannot edit another family child');
select lives_ok($$select public.set_child_goal('30000000-0000-4000-8000-000000001501',(select id from public.children where family_id=gina.family_id() limit 1))$$,'can choose goal for own child');
select lives_ok($$select public.set_child_goal('30000000-0000-4000-8000-000000001501',(select id from public.children where family_id=gina.family_id() limit 1))$$,'goal retry succeeds');
select is((select count(*)::int from public.child_goals where family_id=gina.family_id()),1,'same goal retry creates no cancelled duplicates');
select lives_ok($$select public.set_beta_test_plan(null)$$,'test can be ended');
select is((select source from public.get_family_entitlement()),'free','real entitlement restored');
select public.set_beta_test_plan('pro');
reset role;
update public.beta_test_access set expires_at=now()-interval '1 second' where user_id='00000000-0000-4000-8000-000000001501';
set local role authenticated;
select is((select plan::text from public.get_family_entitlement()),'free','expired test cannot retain Pro');
select throws_ok($$select public.set_beta_test_plan('pro')$$,'42501','beta_access_required','expired tester cannot extend access');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000001501","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000001501","role":"device"}}',true);
select throws_ok($$select public.set_beta_test_plan('pro')$$,'42501','forbidden','child cannot select beta plan');
select throws_ok($$select public.save_child_setup('40000000-0000-4000-8000-000000001504','{"name":"X","birth_year":2020}')$$,'42501','forbidden','child cannot create profiles');
reset role;
-- Beta toggles never rewrite a real subscription; ending the test restores it.
insert into public.store_subscriptions(family_id,platform,product_id,plan,store_key,status,expires_at)
values('10000000-0000-4000-8000-000000001501','apple','gina_plus_monthly','plus','beta-preserve-store','active',now()+interval '1 month');
update public.beta_test_access set expires_at=now()+interval '1 day' where user_id='00000000-0000-4000-8000-000000001501';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000001501","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000001501","role":"parent"}}',true);
select public.set_beta_test_plan('free');
select is((select plan::text from public.get_family_entitlement()),'free','beta can simulate Free over a paid subscription');
select public.set_beta_test_plan(null);
select is((select plan::text from public.get_family_entitlement()),'plus','ending beta restores paid plan');
select is((select source from public.get_family_entitlement()),'store','paid source is preserved');
reset role;
select is((select plan::text from public.store_subscriptions where store_key='beta-preserve-store'),'plus','beta never rewrites the store record');
select * from finish();
rollback;
